            title = "धर्म, डर र स्वर्ग-नरकको अवधारणा",
            subtitle = "के डर र लोभको जगमा उभिएको विश्वासले मानिसलाई साँच्चै स्वतन्त्र बनाउँछ?",
            introduction = "तातो तेलको कराही, शरीर चिर्ने करौती र अनन्त यातनाको नरक एकातिर; अनि कल्पवृक्ष, अप्सरा र कहिल्यै नसकिने सुखभोगको स्वर्ग अर्कोतिर। बाल्यकालदेखि नै हाम्रो कल्पनामा यी दुई चित्रहरू किन यति गहिरो गरी कोरिन्छन्?",
            paragraphs = listOf(
                "कुनै पनि विचार वा संस्थाले मानिसमाथि लामो समयसम्म नियन्त्रण राख्नुपर्यो भने उसले मानव मनोविज्ञानका दुई सबैभन्दा आदिम भावनाहरूलाई समात्छ: डर (Fear) र लोभ (Greed)। स्वर्ग र नरकको अवधारणा यही मनोवैज्ञानिक सूत्रको सबैभन्दा सफल आविष्कार हो।",
                "सानो बच्चालाई खाना खुवाउन वा सुताउन नसक्दा जसरी 'ऊ हाउगुजी आयो!' वा 'चुप लाग्यौ भने चकलेट दिन्छु' भनिन्छ, ठीक त्यसरी नै वयस्क मानव समाजलाई अनुशासनमा राख्ने नाममा मृत्युपछिको दण्ड र पुरस्कारको कथा बुनियो। नियम मान्नेलाई स्वर्गको चकलेट, र प्रश्न गर्ने वा नियम तोड्नेलाई नरकको हाउगुजी!",
                "एकपटक शान्त भएर विचार गरौँ: लगभग ७० वा ८० वर्षको सीमित मानवीय जीवनमा कसैले गरेको गल्तीका लागि उसलाई 'अनन्त कालसम्म' (Eternally) आगोमा पोल्ने वा यातना दिने कुरा कसरी न्यायसंगत हुन सक्छ? संसारको कुनै पनि सभ्य अदालतले सीमित अपराधका लागि असीमित र क्रूर यातनाको सजाय दिँदैन। अझ अनौठो त के भने, कतिपय धार्मिक मान्यताहरूमा मानिसको कर्मभन्दा पनि उसले कुन ईश्वर वा कुन धर्मग्रन्थलाई मान्यो वा मानेन भन्ने आधारमा स्वर्ग र नरक तोकिन्छ।",
                "अर्थात्, एकजना मानिसले जीवनभर कसैको चित्त दुखाएन, इमानदारीपूर्वक बाँच्यो र दिनदुःखीको सेवा गर्यो, तर उसले कुनै विशेष धार्मिक अनुष्ठान वा ईश्वरलाई स्वीकारेन भने ऊ नरक जाने? अनि अर्को मानिसले जीवनभर छलकपट र अन्याय गर्यो, तर अन्तिम समयमा तीर्थ गएर, दान दक्षिणा दिएर वा मन्त्र जपेर आफ्ना सबै पाप पखाल्यो भने ऊ सिधै स्वर्ग जाने? यो कस्तो न्याय प्रणाली हो जहाँ आस्थाले आचरणलाई जित्छ?",
                "बर्ट्रान्ड रसेलले आफ्नो प्रसिद्ध निबन्धमा लेखेका छन्—'धर्म मुख्यतया र प्रथमतः डरमा आधारित छ।' मृत्युको डर, अज्ञातको डर, र हारको डर। तर डरले मानिसलाई आज्ञाकारी त बनाउन सक्छ, विवेकशील र संवेदनशील बनाउन सक्दैन। जहाँ डर हुन्छ, त्यहाँ साँचो प्रेम र स्वतन्त्रता हुनै सक्दैन।",
                "अझ गम्भीर सामाजिक असर त के पर्यो भने, परलोक र स्वर्गको कल्पनामा डुब्दा हामीले यही धरतीको वर्तमान जीवनलाई तुच्छ ठान्न थाल्यौँ। 'यो संसार त मायाजाल हो, दुई दिनको पाहुना घर हो, असली जीवन त मृत्युपछि सुरु हुन्छ' भन्ने सोचले वर्तमानका अन्याय, गरीबी र पीडाहरूप्रति मानिसलाई उदासीन बनाइदियो। यदि यो जीवन केवल अर्को लोकको प्रवेश परीक्षा मात्र हो भने, यहाँको वातावरण, यहाँको समानता र यहाँको मानवीय सुखको मूल्य नै के रह्यो र?",
                "जब मैले स्वर्ग र नरकको यो काल्पनिक भूगोलबाट आफूलाई बाहिर निकालेँ, तब मेरो नजरमा यही पृथ्वीको मूल्य हजार गुणा बढ्यो। मैले बुझेँ—हामीसँग एकअर्कालाई माया गर्न, न्याय गर्न र सुन्दर जीवन बाँच्नका लागि मृत्युपछिको कुनै अर्को लोक छैन; जे छ, यही एकबारको जीवन र यही धरती मात्र छ।",
                "नरकको डर त्याग्नु भनेको उद्दण्ड बन्नु होइन; यो त बाहिरी पुलिसको डरले होइन, आफ्नै अन्तरात्माको उज्यालोले सही बाटो हिँड्न सिक्नु हो।"
            ),
            reflectionQuestion = "यदि भोलि बिहानैदेखि स्वर्गको पुरस्कार र नरकको सजाय दुवैको अस्तित्व छैन भनी पूर्ण प्रमाणित भयो भने, के तपाईंको दैनिक आचरण र अरूप्रतिको व्यवहार बदलिनेछ?",
            memorableQuote = "हामीसँग एकअर्कालाई प्रेम गर्न र न्याय दिन मृत्युपछिको कुनै अर्को लोक छैन; स्वर्ग वा नरक जे बनाउनु छ, हामीले यही धरतीमा आफ्नै व्यवहारबाट बनाउने हो।",
            references = listOf("Bertrand Russell — Why I Am Not a Christian (1927)", "Omar Khayyam / Charvaka Philosophy on Here and Now"),
            readingTimeMinutes = 7
        )
    )
}
